import{_ as a,C as e,c as o,o as s,j as i,G as r,a0 as t,b as n,a as l,w as u,a1 as p}from"./chunks/framework.DKRgXLPU.js";const d=JSON.parse('{"title":"Guia da Sessão: Introdução ao Jogo Mental (2-3 horas)","description":"","frontmatter":{},"headers":[],"relativePath":"pt/mental-journey/session-guide.md","filePath":"pt/mental-journey/session-guide.md"}');const c=a({name:"pt/mental-journey/session-guide.md"},[["render",function(a,d,c,m,h,g){const q=e("AdBanner"),f=e("Mermaid"),v=e("AdInArticle");return s(),o("div",null,[d[1]||(d[1]=i("h1",{id:"guia-da-sessao-introducao-ao-jogo-mental-2-3-horas",tabindex:"-1"},[l("Guia da Sessão: Introdução ao Jogo Mental (2-3 horas) "),i("a",{class:"header-anchor",href:"#guia-da-sessao-introducao-ao-jogo-mental-2-3-horas","aria-label":'Permalink to "Guia da Sessão: Introdução ao Jogo Mental (2-3 horas)"'},"​")],-1)),r(q),d[2]||(d[2]=t('<h2 id="visao-geral" tabindex="-1">Visão geral <a class="header-anchor" href="#visao-geral" aria-label="Permalink to &quot;Visão geral&quot;">​</a></h2><p>Este guia ajuda você a conduzir uma sessão introdutória de 2 a 3 horas sobre treinamento mental para jogadores de petanca. Perfeito para treinadores, dirigentes de clubes ou jogadores experientes que desejam introduzir o treinamento mental em suas equipes.</p><div class="tip custom-block"><p class="custom-block-title">Este guia está dividido em duas seções.</p><ul><li><strong><a href="#for-participants">Para Participantes</a></strong> - O que os jogadores aprenderão</li><li><strong><a href="#for-facilitators">Para Facilitadores</a></strong> - Como conduzir a sessão</li></ul></div><h2 id="acesso-rapido" tabindex="-1">Acesso rápido <a class="header-anchor" href="#acesso-rapido" aria-label="Permalink to &quot;Acesso rápido&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Seção</th><th>Propósito</th><th>Acesso</th></tr></thead><tbody><tr><td><strong>Para Participantes</strong></td><td>O que esperar da sessão</td><td><a href="#for-participants">Ver seção</a></td></tr><tr><td><strong>Para Facilitadores</strong></td><td>Plano de sessão completo e duração</td><td><a href="#para-facilitadores">Ver seção</a></td></tr><tr><td><strong>Materiais da Sessão</strong></td><td>Guias, slides e folhas de exercícios</td><td><a href="/en/mental-journey/materials">Ver Materiais</a></td></tr><tr><td><strong>Lista de verificação de preparação</strong></td><td>O que preparar antes da sessão</td><td><a href="#preparação-1-semana-antes">Ver lista de verificação</a></td></tr></tbody></table><hr><h2 id="para-os-participantes" tabindex="-1">Para os participantes <a class="header-anchor" href="#para-os-participantes" aria-label="Permalink to &quot;Para os participantes&quot;">​</a></h2><h3 id="o-que-esperar" tabindex="-1">O que esperar <a class="header-anchor" href="#o-que-esperar" aria-label="Permalink to &quot;O que esperar&quot;">​</a></h3><p>Esta sessão apresenta o aspecto mental do jogo de petanca através de discussões, exercícios e técnicas práticas que você pode usar imediatamente.</p><p><strong>Você aprenderá:</strong></p><ul><li>Por que o treinamento mental é importante para o desempenho?</li><li>A diferença entre &quot;modo técnico&quot; e &quot;modo de fluxo&quot;</li><li>Como reconhecer e lidar com seu crítico interno</li><li>Técnicas simples para o gerenciamento da pressão arterial.</li><li>Uma rotina básica antes da foto</li></ul><p><strong>O que você vai precisar:</strong></p><ul><li>Mente aberta e disposição para compartilhar</li><li>Caderno e caneta</li><li>Compartilhe suas próprias experiências</li><li>2 a 3 horas de tempo concentrado</li></ul><h3 id="estrutura-da-sessao" tabindex="-1">Estrutura da Sessão <a class="header-anchor" href="#estrutura-da-sessao" aria-label="Permalink to &quot;Estrutura da Sessão&quot;">​</a></h3>',14)),(s(),n(p,null,{default:u(()=>[r(f,{id:"mermaid-157",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BIntrodu%C3%A7%C3%A3o%20%3Cbr%2F%3E%2020%20minutos%5D%20--%3E%20B%5BA%20Zona%20%3Cbr%2F%3E%2040%20minutos%5D%0A%20%20%20%20B%20--%3E%20C%5BQuebrar%20%3Cbr%2F%3E%2010%20minutos%5D%0A%20%20%20%20C%20--%3E%20D%5BCr%C3%ADtico%20Interior%20%3Cbr%2F%3E%2040%20minutos%5D%0A%20%20%20%20D%20--%3E%20E%5BFerramentas%20pr%C3%A1ticas%20%3Cbr%2F%3E%2040%20minutos%5D%0A%20%20%20%20E%20--%3E%20F%5BIntegra%C3%A7%C3%A3o%20%3Cbr%2F%3E%2020%20minutos%5D%0A%20%20%20%20%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20B%20fill%3A%23fff4e1%0A%20%20%20%20style%20C%20fill%3A%23f3e5f5%0A%20%20%20%20style%20D%20fill%3A%23ffe4e1%0A%20%20%20%20style%20E%20fill%3A%23e8f5e9%0A%20%20%20%20style%20F%20fill%3A%23c8e6c9%0A"})]),fallback:u(()=>[...d[0]||(d[0]=[l(" Loading... ",-1)])]),_:1})),d[3]||(d[3]=t('<h3 id="conceitos-chave-que-voce-explorara" tabindex="-1">Conceitos-chave que você explorará <a class="header-anchor" href="#conceitos-chave-que-voce-explorara" aria-label="Permalink to &quot;Conceitos-chave que você explorará&quot;">​</a></h3><h4 id="_1-a-zona-estado-de-fluxo" tabindex="-1">1. A Zona (Estado de Fluxo) <a class="header-anchor" href="#_1-a-zona-estado-de-fluxo" aria-label="Permalink to &quot;1. A Zona (Estado de Fluxo)&quot;">​</a></h4><ul><li>A sensação de quando tudo se encaixa.</li><li>Por que pensar na técnica atrapalha o desempenho</li><li>A &quot;transição&quot; do planejamento para a execução.</li></ul><h4 id="_2-o-critico-interior" tabindex="-1">2. O Crítico Interior <a class="header-anchor" href="#_2-o-critico-interior" aria-label="Permalink to &quot;2. O Crítico Interior&quot;">​</a></h4><ul><li>Como a autocrítica negativa afeta o desempenho</li><li>A diferença entre o crítico interno e o treinador interno</li><li>Observação neutra versus julgamento severo</li></ul><h4 id="_3-resposta-a-pressao" tabindex="-1">3. Resposta à pressão <a class="header-anchor" href="#_3-resposta-a-pressao" aria-label="Permalink to &quot;3. Resposta à pressão&quot;">​</a></h4><ul><li>Por que você joga de forma diferente em competições?</li><li>Sinais físicos de pressão</li><li>Técnicas de reinicialização rápida</li></ul><h4 id="_4-ferramentas-praticas" tabindex="-1">4. Ferramentas Práticas <a class="header-anchor" href="#_4-ferramentas-praticas" aria-label="Permalink to &quot;4. Ferramentas Práticas&quot;">​</a></h4><ul><li>Reinicialização em 3 respirações</li><li>rotina simples antes da foto</li><li>Protocolo de recuperação de erros</li></ul><h3 id="o-que-levar" tabindex="-1">O que levar <a class="header-anchor" href="#o-que-levar" aria-label="Permalink to &quot;O que levar&quot;">​</a></h3><p><strong>Obrigatório:</strong></p><ul><li>Você e suas experiências</li><li>Disposição para participar</li></ul><p><strong>Opcional:</strong></p><ul><li>Exemplos de desafios mentais que você enfrenta</li><li>Perguntas sobre situações específicas</li><li>Caderno para anotações pessoais</li></ul><h3 id="apos-a-sessao" tabindex="-1">Após a sessão <a class="header-anchor" href="#apos-a-sessao" aria-label="Permalink to &quot;Após a sessão&quot;">​</a></h3><p>Você receberá:</p><ul><li>Resumo dos principais conceitos</li><li>Exercícios práticos para a semana</li><li>Links para módulos educacionais detalhados</li><li>Modelo de objetivos para o desenvolvimento de jogos mentais</li></ul>',17)),r(v),d[4]||(d[4]=t('<hr><h2 id="para-facilitadores" tabindex="-1">Para Facilitadores <a class="header-anchor" href="#para-facilitadores" aria-label="Permalink to &quot;Para Facilitadores&quot;">​</a></h2><h3 id="lista-de-verificacao-de-preparacao" tabindex="-1">Lista de verificação de preparação <a class="header-anchor" href="#lista-de-verificacao-de-preparacao" aria-label="Permalink to &quot;Lista de verificação de preparação&quot;">​</a></h3><p><strong>1 semana antes:</strong></p><ul><li>[ ] Reserve um quarto por 2 a 3 horas.</li><li>[ ] Convide de 6 a 12 participantes.</li><li>[ ] Adicione as páginas de materiais aos seus favoritos (consulte <a href="/en/mental-journey/materials">Materiais</a>)</li><li>[ ] Analise este guia cuidadosamente.</li><li>[ ] Prepare um flip chart ou um quadro branco.</li></ul><p><strong>1 dia antes:</strong></p><ul><li>[ ] Confirme presença</li><li>[ ] Preparar a sala (com assentos em círculo)</li><li>[ ] Teste qualquer tecnologia (slides, etc.)</li><li>[ ] Preparar os materiais</li></ul><p><strong>1 hora antes:</strong></p><ul><li>[ ] Chegue cedo</li><li>[ ] Disponha os assentos em círculo.</li><li>[ ] Preparar materiais</li><li>[ ] Centralize-se</li></ul><h3 id="seu-papel-como-facilitador" tabindex="-1">Seu papel como facilitador <a class="header-anchor" href="#seu-papel-como-facilitador" aria-label="Permalink to &quot;Seu papel como facilitador&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Importante</p><p>Você <strong>não</strong> é um terapeuta ou um coach técnico. Você é um <strong>facilitador</strong> que:</p><ul><li>Discussão sobre guias</li><li>Cria um espaço seguro</li><li>Conecta conceitos à experiência.</li><li>Gerencia a dinâmica de grupo</li></ul></div><p><strong>Habilidades Essenciais:</strong></p><ul><li>Escuta ativa</li><li>Presença neutra</li><li>Gerenciar diferentes personalidades</li><li>Saber a hora de seguir em frente</li></ul><h3 id="plano-de-sessao-detalhado" tabindex="-1">Plano de Sessão Detalhado <a class="header-anchor" href="#plano-de-sessao-detalhado" aria-label="Permalink to &quot;Plano de Sessão Detalhado&quot;">​</a></h3><hr><h4 id="parte-1-introducao-20-minutos" tabindex="-1">Parte 1: Introdução (20 minutos) <a class="header-anchor" href="#parte-1-introducao-20-minutos" aria-label="Permalink to &quot;Parte 1: Introdução (20 minutos)&quot;">​</a></h4><p><strong>Objetivos:</strong></p><ul><li>Criar segurança psicológica</li><li>Defina expectativas</li><li>Criar conexão de grupo</li></ul><p><strong>Roteiro:</strong></p><p>&quot;Sejam todos bem-vindos. Esta sessão é sobre o aspecto mental do jogo de petanca - os pensamentos, sentimentos e padrões que afetam o seu desempenho.&quot;</p><p><strong>Regras básicas:</strong></p><ol><li>O que é compartilhado aqui, fica aqui.</li><li>Sem julgamentos sobre as experiências alheias.</li><li>A participação é voluntária.</li><li>Não existem respostas erradas.</li></ol><p><strong>Perguntas rápidas:</strong> Nome, há quanto tempo você joga, um desafio mental que você enfrenta.</p><p><strong>Notas do Facilitador:</strong></p><ul><li>Comece por modelar a vulnerabilidade.</li><li>Mantenha as apresentações breves (1 minuto cada).</li><li>Observe os temas comuns</li><li>Valide todas as respostas.</li></ul><hr><h4 id="parte-2-o-estado-de-zona-fluxo-40-minutos" tabindex="-1">Parte 2: O Estado de Zona/Fluxo (40 minutos) <a class="header-anchor" href="#parte-2-o-estado-de-zona-fluxo-40-minutos" aria-label="Permalink to &quot;Parte 2: O Estado de Zona/Fluxo (40 minutos)&quot;">​</a></h4><p><strong>Objetivos:</strong></p><ul><li>Compreender os estados de fluxo</li><li>Reconhecer o modo técnico versus o modo de fluxo</li><li>Aprenda o conceito de &quot;interruptor&quot;</li></ul><p><strong>Pergunta inicial:</strong> &quot;Pense em uma vez em que você jogou sua melhor partida de petanca. Como você se sentiu? O que foi diferente?&quot;</p><p><strong>Sugestões para discussão:</strong></p><ol><li>&quot;Quantos de vocês já tiveram jogos em que tudo simplesmente se encaixou?&quot;</li><li>&quot;No que você estava pensando durante esses momentos?&quot;</li><li>&quot;Qual a diferença entre isso e quando você está passando por dificuldades?&quot;</li></ol><p><strong>Pontos-chave de ensino:</strong></p><p>Use o quadro branco para desenhar:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PLANNING MODE          →    EXECUTION MODE</span></span>\n<span class="line"><span>(Outside circle)            (Inside circle)</span></span>\n<span class="line"><span>- Analyze situation         - Eyes on target</span></span>\n<span class="line"><span>- Choose strategy           - Trust training</span></span>\n<span class="line"><span>- Decide throw type         - Automatic movement</span></span></code></pre></div><p><strong>Exercício: A Troca (10 minutos)</strong></p><p>&quot;Vamos praticar o momento da troca:</p><ol><li>Ficar de pé</li><li>Imagine que você está fora do círculo - pense em uma tacada.</li><li>Respire fundo.</li><li>Dê um passo à frente (para dentro de um círculo imaginário)</li><li>Ao dar o passo, deixe de lado a análise.</li><li>&quot;Concentre-se apenas em um alvo imaginário&quot;</li></ol><p><strong>Relatório:</strong></p><ul><li>&quot;O que você notou?&quot;</li><li>&quot;Foi fácil ou difícil deixar de pensar?&quot;</li><li>&quot;Como isso se aplicaria em jogos reais?&quot;</li></ul><hr><h4 id="parte-3-intervalo-10-minutos" tabindex="-1">Parte 3: Intervalo (10 minutos) <a class="header-anchor" href="#parte-3-intervalo-10-minutos" aria-label="Permalink to &quot;Parte 3: Intervalo (10 minutos)&quot;">​</a></h4><p><strong>Ações do Facilitador:</strong></p><ul><li>Incentive discussões informais.</li><li>Observe a energia do grupo</li><li>Prepare-se para a próxima seção.</li></ul><hr><h4 id="parte-4-o-critico-interior-40-minutos" tabindex="-1">Parte 4: O Crítico Interior (40 minutos) <a class="header-anchor" href="#parte-4-o-critico-interior-40-minutos" aria-label="Permalink to &quot;Parte 4: O Crítico Interior (40 minutos)&quot;">​</a></h4><p><strong>Objetivos:</strong></p><ul><li>Reconheça padrões de diálogo interno negativo.</li><li>Diferencie o crítico interno do treinador interno.</li><li>Pratique a observação neutra.</li></ul><p><strong>Abertura:</strong> &quot;Todos nós temos uma voz interior que comenta nosso desempenho. Às vezes é útil, às vezes é dura. Vamos explorar isso.&quot;</p><p><strong>Exercício: Inventário do Crítico Interior (15 minutos)</strong></p><p>&quot;Em seu papel, escreva:</p><ol><li>O que sua voz interior diz depois de um arremesso ruim</li><li>O que isso significa quando você está sob pressão</li><li>O que isso diz sobre suas habilidades&quot;</li></ol><p><em>Dê 5 minutos para escrever</em></p><p>&quot;Agora, quem está disposto a compartilhar um exemplo?&quot;</p><p><strong>Notas do Facilitador:</strong></p><ul><li>Normalizar a autocrítica severa</li><li>Não tente &quot;consertar&quot; ninguém.</li><li>Procure padrões comuns</li></ul><p><strong>Aula: Crítico Interior vs. Orientador Interior (15 minutos)</strong></p><p>Desenhe duas colunas no quadro branco:</p><table tabindex="0"><thead><tr><th>Crítico Interior</th><th>Treinador Interior</th></tr></thead><tbody><tr><td>&quot;Como você pôde perder isso?!&quot;</td><td>&quot;Isso foi para a esquerda&quot;</td></tr><tr><td>&quot;Você sempre se engasga&quot;</td><td>&quot;Vamos tentar novamente&quot;</td></tr><tr><td>&quot;Você é terrível&quot;</td><td>&quot;O que posso aprender?&quot;</td></tr></tbody></table><p><strong>Discussão:</strong></p><ul><li>&quot;Percebe a diferença?&quot;</li><li>&quot;Qual voz ajuda na performance?&quot;</li><li>&quot;Você consegue mudar a voz?&quot;</li></ul><p><strong>Prática: Reestruturação Mental (10 minutos)</strong></p><p>&quot;Escolha uma das suas afirmações de Crítico Interior. Como um Coach Interior a expressaria?&quot;</p><p>Compartilhe exemplos.</p><hr><h4 id="parte-5-ferramentas-praticas-40-minutos" tabindex="-1">Parte 5: Ferramentas Práticas (40 minutos) <a class="header-anchor" href="#parte-5-ferramentas-praticas-40-minutos" aria-label="Permalink to &quot;Parte 5: Ferramentas Práticas (40 minutos)&quot;">​</a></h4><p><strong>Objetivos:</strong></p><ul><li>Aprenda a técnica de reinicialização em 3 respirações.</li><li>Crie uma rotina simples antes da gravação</li><li>Entenda a recuperação de erros</li></ul><p><strong>Ferramenta 1: Reinicialização em 3 respirações (10 minutos)</strong></p><p>&quot;Este é o seu botão de reinicialização de emergência. Use-o quando sentir que a pressão está aumentando.&quot;</p><p><strong>Demonstrar:</strong></p><ol><li>Inspire contando até 4.</li><li>Mantenha a posição por 2 tempos.</li><li>Expire contando até 6.</li><li>Repita 3 vezes</li></ol><p>&quot;Vamos praticar juntos agora.&quot;</p><p><em>Conduza o grupo através de 3 ciclos</em></p><p><strong>Relatório:</strong></p><ul><li>&quot;O que você notou em seu corpo?&quot;</li><li>&quot;Quando você poderia usar isso?&quot;</li></ul><p><strong>Ferramenta 2: Rotina simples de preparação para a foto (15 minutos)</strong></p><p>&quot;Uma rotina ajuda você a passar do planejamento à execução de forma consistente.&quot;</p><p><strong>Estrutura básica:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Outside Circle (Planning):</span></span>\n<span class="line"><span>- Look at situation</span></span>\n<span class="line"><span>- Decide on throw</span></span>\n<span class="line"><span>- See the result in your mind</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Walking to Circle (Transition):</span></span>\n<span class="line"><span>- One deep breath</span></span>\n<span class="line"><span>- Let go of analysis</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Inside Circle (Execution):</span></span>\n<span class="line"><span>- Eyes on target only</span></span>\n<span class="line"><span>- Trust your training</span></span>\n<span class="line"><span>- Execute</span></span></code></pre></div><p><strong>Exercício:</strong> &quot;Crie sua própria rotina de 3 passos. Anote-a.&quot;</p><p>Compartilhe exemplos.</p><p><strong>Ferramenta 3: Protocolo de Recuperação de Erros (15 minutos)</strong></p><p>&quot;Jogadores de elite não cometem menos erros. Eles se recuperam mais rápido.&quot;</p><p><strong>Protocolo de 3 etapas:</strong></p><ol><li><strong>Observe</strong> - Apresente o fato de forma neutra (&quot;Aquilo foi para a esquerda&quot;)</li><li><strong>Aprender</strong> - Extrair informações (&quot;Vento mais forte do que eu pensava&quot;)</li><li><strong>Recomeçar</strong> - Seguir em frente (recomeço de 3 respirações, olhar para a frente)</li></ol><p><strong>Prática:</strong> &quot;Pense em um erro recente. Descreva os 3 passos.&quot;</p><hr><h4 id="parte-6-integracao-e-encerramento-20-minutos" tabindex="-1">Parte 6: Integração e Encerramento (20 minutos) <a class="header-anchor" href="#parte-6-integracao-e-encerramento-20-minutos" aria-label="Permalink to &quot;Parte 6: Integração e Encerramento (20 minutos)&quot;">​</a></h4><p><strong>Objetivos:</strong></p><ul><li>Consolidar o aprendizado</li><li>Criar planos de ação</li><li>Fornecer recursos</li></ul><p><strong>Questões para reflexão:</strong></p><ol><li>&quot;Qual é a principal lição que você leva consigo?&quot;</li><li>&quot;Qual é uma coisa que você vai experimentar esta semana?&quot;</li><li>&quot;Que perguntas ainda restam?&quot;</li></ol><p><strong>Planejamento de Ações (10 minutos)</strong></p><p>&quot;Na sua folha de atividades, escreva:</p><ol><li>Uma técnica que você praticará esta semana</li><li>Quando/onde você vai praticar isso</li><li>Como você acompanhará seu progresso&quot;</li></ol><p><strong>Recursos:</strong></p><ul><li>Distribua a folha de resumo.</li><li>Compartilhe o site: carreau.app</li><li>Módulo inicial recomendado: <a href="/en/education/the-zone/">The Zone</a></li></ul><p><strong>Círculo de Encerramento:</strong> &quot;Uma palavra para descrever como você está se sentindo agora.&quot;</p><p><strong>Considerações finais:</strong> &quot;O treinamento mental é uma habilidade como qualquer outra - requer prática. Comece devagar, seja paciente consigo mesmo e observe as mudanças. Agradeço sua abertura hoje.&quot;</p><hr><h3 id="dicas-para-o-facilitador" tabindex="-1">Dicas para o Facilitador <a class="header-anchor" href="#dicas-para-o-facilitador" aria-label="Permalink to &quot;Dicas para o Facilitador&quot;">​</a></h3><h4 id="lidando-com-situacoes-dificeis" tabindex="-1">Lidando com situações difíceis <a class="header-anchor" href="#lidando-com-situacoes-dificeis" aria-label="Permalink to &quot;Lidando com situações difíceis&quot;">​</a></h4><p><strong>Se alguém domina:</strong></p><ul><li>&quot;Obrigado [nome]. Vamos ouvir a opinião dos outros.&quot;</li><li>Use a alternância de turnos estruturada.</li></ul><p><strong>Se alguém resistir:</strong></p><ul><li>Não discuta</li><li>&quot;Essa é uma perspectiva válida. O que os outros pensam?&quot;</li><li>Alinhe-se com a preocupação deles</li></ul><p><strong>Se alguém ficar emocionado:</strong></p><ul><li>Normalize-o</li><li>&quot;Isso toca em algo real. Obrigada por compartilhar.&quot;</li><li>Não tente consertar</li></ul><p><strong>Caso a discussão fique estagnada:</strong></p><ul><li>Use instruções específicas</li><li>Compartilhe seu próprio exemplo.</li><li>Passe para um exercício</li></ul><h4 id="gestao-de-energia" tabindex="-1">Gestão de energia <a class="header-anchor" href="#gestao-de-energia" aria-label="Permalink to &quot;Gestão de energia&quot;">​</a></h4><p><strong>Alta energia:</strong> Utilize exercícios e movimento <strong>Baixa energia:</strong> Faça perguntas provocativas <strong>Dispersos:</strong> Restaure à estrutura <strong>Tempo verbal:</strong> Use humor ou faça uma pausa.</p><h3 id="pos-sessao" tabindex="-1">Pós-sessão <a class="header-anchor" href="#pos-sessao" aria-label="Permalink to &quot;Pós-sessão&quot;">​</a></h3><p><strong>Seguir:</strong></p><ul><li>Enviar e-mail de resumo em até 24 horas.</li><li>Inclua links para recursos.</li><li>Ofereça-se para responder às perguntas.</li><li>Agende uma sessão de acompanhamento opcional.</li></ul><p><strong>Autoavaliação:</strong></p><ul><li>O que funcionou bem?</li><li>O que você mudaria?</li><li>O que te surpreendeu?</li><li>O que você aprendeu?</li></ul>',118)),r(q),d[5]||(d[5]=t('<hr><h2 id="materiais" tabindex="-1">Materiais <a class="header-anchor" href="#materiais" aria-label="Permalink to &quot;Materiais&quot;">​</a></h2><ul><li><a href="/en/mental-journey/materials#participant-guide">Guia do Participante</a></li><li><a href="/en/mental-journey/materials#facilitator-slides">Slides do Facilitador</a></li><li><a href="/en/mental-journey/materials#summary-sheet">Folha Resumo</a></li><li><a href="/en/mental-journey/materials#exercise-worksheets">Folhas de exercícios</a></li></ul><hr><div class="tip custom-block"><p class="custom-block-title">Pronto para facilitar?</p><ol><li>Analise este guia cuidadosamente.</li><li>Baixe os materiais</li><li>Pratique os exercícios você mesmo</li><li>Agende sua sessão</li><li>Confie no processo</li></ol></div>',5))])}]]);export{d as __pageData,c as default};
